#!/usr/bin/env bash
# clean-builds.sh: delete build/test artifacts that accumulate on disk.
#
# Default set (safe, regenerated by the normal build/test flow):
#   dist/                                    goreleaser snapshot output
#   coverage, coverage.out                   stray test binaries / coverage profiles
#   .book-scratch/bin                        book demo build output
#   testsuite/agenttest_fixtures/*/target    cargo test-fixture output
#
# Extra sets (opt-in, cost time or network to rebuild):
#   --deep       .gocache/ plus /tmp/relurpify-go-cache and /tmp/relurpify-go-tmp
#                (Makefile GOCACHE/GOTMPDIR; rebuild = recompile only)
#   --modcache   .gomodcache/ (rebuild = module re-download; Makefile builds run
#                with GOPROXY=off, so keep this cache if you build offline)
#
# Usage: tooling/clean-builds.sh [--deep] [--modcache] [-y|--yes]
# Without --yes the script only reports what it would delete and the space it
# would free.
set -euo pipefail

repo_root="$(git rev-parse --show-toplevel 2>/dev/null)" || {
	echo "error: not inside a git repository" >&2
	exit 1
}
if [ ! -f "$repo_root/Makefile" ]; then
	echo "error: $repo_root does not look like the relurpify repo" >&2
	exit 1
fi

yes=0
deep=0
modcache=0
for arg in "$@"; do
	case "$arg" in
	-y | --yes) yes=1 ;;
	--deep) deep=1 ;;
	--modcache) modcache=1 ;;
	*)
		echo "usage: $0 [--deep] [--modcache] [-y|--yes]" >&2
		exit 2
		;;
	esac
done

targets=()
targets+=("dist")
targets+=("coverage")
targets+=("coverage.out")
targets+=(".book-scratch/bin")
for t in "$repo_root"/testsuite/agenttest_fixtures/*/target; do
	[ -e "$t" ] && targets+=("${t#"$repo_root"/}")
done
if [ "$deep" -eq 1 ]; then
	targets+=(".gocache" "/tmp/relurpify-go-cache" "/tmp/relurpify-go-tmp")
fi
if [ "$modcache" -eq 1 ]; then
	targets+=(".gomodcache")
fi

total=0
existing=()
for t in "${targets[@]}"; do
	path="$repo_root/$t"
	[ -e "$path" ] || continue
	existing+=("$t")
	size="$(du -sm "$path" 2>/dev/null | cut -f1)"
	total=$((total + size))
done

if [ "${#existing[@]}" -eq 0 ]; then
	echo "nothing to clean"
	exit 0
fi

printf '%-45s %10s\n' PATH 'SIZE (MB)'
for t in "${existing[@]}"; do
	size="$(du -sm "$repo_root/$t" 2>/dev/null | cut -f1)"
	printf '%-45s %10s\n' "$t" "$size"
done
printf '%-45s %10s\n' TOTAL "$total"

if [ "$yes" -ne 1 ]; then
	echo "dry run: pass -y to delete"
	exit 0
fi

for t in "${existing[@]}"; do
	rm -rf -- "$repo_root/$t"
	echo "deleted $t"
done
echo "freed ~${total}MB"
